TLM.f("Sancti/01-26",{"officium":"S. Polycarpi Episcopi et Martyris","rule":["vide C2;","Gloria"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Dan 3:84; 3:87"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."},{"k":"ref","la":"Dan 3:57"},{"k":"text","la":"Benedícite, ómnia ópera Dómini, Dómino: laudáte et superexaltáte eum in sǽcula."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."}],"Oratio":[{"k":"text","la":"Deus, qui nos beáti Polycárpi Mártyris tui atque Pontíficis ánnua sollemnitáte lætíficas: concéde propítius; ut, cujus natalítia cólimus, de ejúsdem étiam protectióne gaudeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Joánnis Apóstoli"},{"k":"ref","la":"1 Joann 3:10-16"},{"k":"text","la":"Caríssimi: Omnis qui non est justus, non est ex Deo, et qui non díligit fratrem suum: quóniam hæc est annuntiátio, quam audístis ab inítio, ut diligátis altérutrum. Non sicut Cain, qui ex malígno erat, et occídit fratrem suum. Et propter quid occídit eum? Quóniam ópera ejus malígna erant: fratris autem ejus justa. Nolíte mirári fratres, si odit vos mundus. Nos scimus quóniam transláti sumus de morte ad vitam, quóniam dilígimus fratres. Qui non díligit, manet in morte: omnis qui odit fratrem suum, homicída est. Et scitis, quóniam omnis homicída non habet vitam ætérnam in semetípso manéntem. In hoc cognóvimus caritátem Dei, quóniam ille ánimam suam pro nobis pósuit: et nos debémus pro frátribus ánimas pónere."}],"Graduale":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum."},{"k":"text","la":"Et constituísti eum super ópera mánuum tuárum, Dómine. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hic est Sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum."},{"k":"text","la":"Et constituísti eum super ópera mánuum tuárum, Dómine.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:26-32"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nihil est opértum, quod non revelábitur; et occúltum, quod non sciétur. Quod dico vobis in ténebris, dícite in lúmine: et quod in aure audítis, prædicáte super tecta. Et nolíte timére eos, qui occídunt corpus, ánimam autem non possunt occídere; sed pótius timéte eum, qui potest et ánimam et corpus pérdere in gehénnam. Nonne duo pásseres asse véneunt: et unus ex illis non cadet super terram sine Patre vestro? Vestri autem capílli cápitis omnes numeráti sunt. Nolíte ergo timére: multis passéribus melióres estis vos. Omnis ergo, qui confitébitur me coram homínibus, confitébor et ego eum coram Patre meo, qui in coelis est."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, dicáta sanctífica: et, intercedénte beáto Polycárpo Mártyre tuo atque Pontífice, per éadem nos placátus inténde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedénte beáto Polycárpo Mártyre tuo atque Pontífice, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6fc068ff728b99e0":{"t":"Dn 3, 84 et 87, Dn 3, 57\n(Dn 3, 84 i 87) Svećenici Božji, blagoslivljajte Gospodina! Sveti i ponizni, srcem, hvalite Boga! (Dn 3, 57) Blagoslivljajte, sva djela Gospodnja, Gospodina, hvalite i uzvisujte ga dovijeka.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dn 3, 84 i 87) Svećenici Božji, blagoslivljajte Gospodina! Sveti i ponizni, srcem, hvalite Boga!","kn":"(Dan. 3, 84, 87). Blagosivajte Gospodina, svećenici Božji; hvalite Boga, sveti i ponizni srcem. (Dani. 3, 57) Blagosivajte Gospodina, sva djela Gospodnja, slavite ga i veličajte, u vjekove! Slava Ocu . . . Blagosivajte . . .","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"348d6ad822521c1c":{"t":"<i>Pomolimo se</i>.\nBože koji nas razveseljuješ svetkovinom blaženoga Polikarpa tvoga mučenika i biskupa, daj milostivo da se radujemo zaštiti onoga kojeg rođendan slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, preblagi Bože, koji nais razveseljuješ svečanom godišnjicom blaženoga I., .Tvoga mučenika i biskupa, da se radujemo zaštiti onoga, kojega rođeni dan slavimo. Po G. n.","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"09d9563efea1128b":{"t":"1 Iv 3, 10-16\nČitanje Poslanice bl. Ivana apostola. Predragi, tko nije pravedan i tko ne ljubi svoga brata nije od Boga, jer je ovo prva vijest što ste je čuli od početka, da ljubite jedni druge. Ne kao Kain koji je bio od zloga i ubio je svoga brata. A zašto ga je ubio? Jer su njegova djela bila zla. a bratova mu pravedna. Ne čudite se, braćo, ako vas svijet mrzi. Mi znamo, da smo od smrti preneseni u život, jer ljubimo braću. Tko ne ljubi ostaje u smrti. Tko mrzi svoga brata, taj je ubojica, a znate da ni jedan ubojica nema u sebi trajnoga vječnog života. Božju ljubav smo spoznali po tome što se on žrtvovao za nas. Tako smo se i mi dužni žrtvovati za braću!","kn":"Čitanje poslanice bi. Ivana apostola (I 3 10-16) redragi! Nitko, koji ,ne čini pravde, nije od Boga. 1 koji ne ljubi brata svojega. Jer je ovo navještenje, koje custe iz početka, da ljubimo jedan drugoga. Ne kao što Kain bijaše od nečastivoga i ubio je brata svojega. I zašto ga je ubio? Jer djela njegova bijahu zla, a brata mu pravedna. Ne čudite se. braco, ako svijet mrzi na vas. Mi znamo-, da smo prešli .iz smrti u život, jer ljubimo braću:’ tko ne ljubi, ostaje u smrti. Svaki onaj, koji mrzi na brata svojega, ubojica je; a znate, da nijedan ubojica nema_ u sebi vječnoga života. Po tomu smo upoznali ljubav, što je On za nas život svoj položio. I mi smo dužni polagati život svoj za braću.","knRef":"Kniewald 1942, str. 492–493 (snimka 247) (OCR)"},"6dc7e0e935655ab8":{"t":"Ps 8, 6-7\nOkrunio si ga slavom i čašću i postavio si ga nad djela svojih ruku, Gospodine.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je svećenik koga je okrunio Gospodin. <i>Aleluja</i>.","kn":"(Ps. 8, 6-7). Okrunio si ga slavom i čašću i postavio si ga nad sva djela tvoja. Gospodine!\n\nAleluja, aleluja! Ovo je svećenik, koga je okrunio Gospođin, aleluja!","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"c48fa5c136bd31ce":{"t":"Mt 10, 26-32\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Ništa nema sakriveno što se neće otkriti, ni tajno što se neće saznati. Što vam kažem u tami govorite na svjetlu, i što čujete na uho propovijedajte na krovovima. Ne bojte se onih koji ubijaju tijelo, ali ne mogu ubiti duše, nego se više bojte onoga koji može i dušu i tijelo baciti i kazniti u paklu. Ne prodaju li se dva vrapca za jedan novčić? I nijedan od njih neće pasti na zemlju bez vašega Oca. A vaše su vlasi na glavi sve izbrojene. Ne bojte se dakle! Vi ste vrjedniji nego mnogo vrabaca. A svakoga koji mene prizna pred ljudima priznat ću i ja pred svojim nebeskim Ocem.","kn":"t Slijedi sv. evanđelje po Mateju (10, 26-32). U ono vrijeme reče Isus svojim učenicima': Ništa nema sakrivena, što se ne će otkriti, ni tajna, što se ne će saznati. Sto vam kažem u tami, govorite na svijetlu, i što čujete na uho, propovijedajte na krovovima. Ne bojte se onih, koji ubijaju tijelo, ali ne mogu ubiti duše, nego se više bojte onoga, koji niože i dušu i tijelo po'gubiti u pakao.. Ne prodaju li se dva vrapca za jedan novčić? I nijedan od njih ne će pasti na zemlju bez vašega Oca. A vaše su vlasi na glavi sve Izbrojene. Ne bojte se dakle: VI ste vrijedniji nego mnogo vrabaca. A svakoga, koji mene prizna pred ljudima, priznat ću i ja pred svojim nebeskim Ocem.","knRef":"Kniewald 1942, str. 796–797 (snimka 399) (OCR)"},"c1545941e0b9c017":{"t":"Ps 88, 21-22\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja.","kn":"(Ps. 88, 21, 22). Izabrao sam Davida za slugu svoga i pomazao sam ga mojim svetim uuem. Moja će ga ruka i mišica će ga moja krijepiti, aleluja. .","knRef":"Kniewald 1942, str. 560–561 (snimka 281) (OCR)"},"ce3c1975ee33832a":{"t":"Posveti, Gospodine, darove tebi prikazane i njima umilostivljen pogledaj na nas po zagovoru blaženog Polikarpa tvoga mučenika i biskupa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, Gospodine, namijenjene Ti darove, te njima umilostivljen, a zagovorom blaženoga I., Tvoga mučenika i biskupa, pogledaj na nas. Po G. n.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"f865cc96d8c6795d":{"t":"Ps 20, 4\nOkrunio si ga, Gospodine, krunom od dragoga kamenja.","kn":"(Ps. 20, 4). Postavio si, Gospoidine, na glavu njegovu krunu od dragoga kamenja.","knRef":"Kniewald 1942, str. 696–697 (snimka 349) (OCR)"},"cd7067abb6fdd756":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni sudjelovanjem u svetom daru, molimo, Gospodine Bože naš, da po zagovoru tvojeg blaženog mučenika i biskupa Polikarpa osjetimo učinak tajne, koju slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom blaženoga I., Tvoga mučenika i biskupa, osjetimo djelovanje svetih tajna, koje izvršuijemo. Po G. n.","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"cc10f9dfa0e65700":{"t":"Ps 8, 6-7\nOkrunio si ga slavom i čašću i postavio si ga nad djela svojih ruku, Gospodine.\n\nPs 111, 1-3\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen. U njegovu je domu slava i bogatstvo, i njegova pravednost ostaje u vijeke vjekova."}}});
